CREATE TABLE audience_import_plans (fingerprint TEXT PRIMARY KEY, principal_id TEXT NOT NULL, plan_json TEXT NOT NULL, source_digest TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE mango_audience_hashes (id TEXT PRIMARY KEY, contact_id TEXT NOT NULL, channel TEXT NOT NULL, destination_hash TEXT NOT NULL, owned_opt_out_id TEXT, owned_suppression_ids TEXT NOT NULL);
CREATE TABLE consent_capture_metadata (id TEXT PRIMARY KEY, contact_id TEXT NOT NULL, capture_ip TEXT, confirmation_ip TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TRIGGER audience_capture_metadata_erasure AFTER DELETE ON contacts BEGIN
 DELETE FROM consent_capture_metadata WHERE contact_id=OLD.id;
 DELETE FROM mango_audience_hashes WHERE contact_id=OLD.id;
 DELETE FROM mango_import_revisions WHERE contact_id=OLD.id;
END;
CREATE TRIGGER audience_capture_metadata_merge AFTER UPDATE OF contact_id ON consent_evidence BEGIN
 UPDATE consent_capture_metadata SET contact_id=NEW.contact_id WHERE id=NEW.id;
END;
CREATE TABLE audience_signup_requests (id TEXT PRIMARY KEY, destination_hash TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE audience_import_observations (id TEXT PRIMARY KEY,contact_id TEXT NOT NULL,source_file TEXT NOT NULL,source_row INTEGER NOT NULL,source_status TEXT NOT NULL,capture_method TEXT NOT NULL,capture_source TEXT NOT NULL,optin_time TEXT,confirm_time TEXT,capture_ip TEXT,confirmation_ip TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TRIGGER audience_import_observations_erasure AFTER DELETE ON contacts BEGIN DELETE FROM audience_import_observations WHERE contact_id=OLD.id; END;
CREATE TRIGGER audience_import_metadata_merge AFTER INSERT ON contact_merges BEGIN
 UPDATE audience_import_observations SET contact_id=NEW.survivor_contact_id WHERE contact_id=NEW.merged_contact_id;
 UPDATE mango_audience_hashes SET contact_id=NEW.survivor_contact_id WHERE contact_id=NEW.merged_contact_id;
END;
CREATE UNIQUE INDEX audience_import_plans_source_actor ON audience_import_plans(source_digest,principal_id);

CREATE TABLE IF NOT EXISTS ik_jobs (
 id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL,
 mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, fingerprint TEXT NOT NULL,
 operation_key TEXT NOT NULL, plan_json TEXT NOT NULL, state TEXT NOT NULL,
 checkpoint INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL, fence INTEGER NOT NULL DEFAULT 0,
 lease_token TEXT, lease_expires INTEGER, error TEXT,
 UNIQUE(destination, principal_id, operation_key)
);
CREATE TABLE IF NOT EXISTS ik_original_sets (
 job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id), version INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ik_originals (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), kind TEXT NOT NULL, original_key TEXT NOT NULL,
 name TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, bytes BLOB,
 PRIMARY KEY(job_id,kind,original_key)
);
CREATE TABLE IF NOT EXISTS ik_sources (
 identity TEXT PRIMARY KEY, source_hash TEXT NOT NULL, mapping_version TEXT NOT NULL,
 effects_hash TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES ik_jobs(id)
);
CREATE TABLE IF NOT EXISTS ik_provenance (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, effect_ordinal INTEGER NOT NULL,
 source_identity TEXT NOT NULL, destination TEXT NOT NULL, target_kind TEXT NOT NULL,
 target_id TEXT NOT NULL, reversed INTEGER NOT NULL DEFAULT 0, record_json TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS ik_active_target ON ik_provenance(destination,target_kind,target_id) WHERE reversed=0;
CREATE TABLE IF NOT EXISTS ik_stages (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), fence INTEGER NOT NULL, effect_id TEXT NOT NULL,
 sha256 TEXT NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(job_id,fence,effect_id)
);
CREATE TABLE IF NOT EXISTS ik_batches (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), action TEXT NOT NULL, position INTEGER NOT NULL,
 end_position INTEGER NOT NULL, fence INTEGER NOT NULL, PRIMARY KEY(job_id,action,position)
);
CREATE TABLE IF NOT EXISTS ik_targets (
 destination TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL,
 revision TEXT NOT NULL, value_json TEXT NOT NULL, attachment_json TEXT,
 PRIMARY KEY(destination,kind,id)
);
CREATE TABLE IF NOT EXISTS ik_d1_history (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, effect_ordinal INTEGER NOT NULL, source_identity TEXT NOT NULL, destination TEXT NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, reversed INTEGER NOT NULL CHECK(reversed=0), record_json TEXT NOT NULL, successor_id TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS ik_d1_history_job ON ik_d1_history(job_id);
CREATE TABLE IF NOT EXISTS ik_d1_entries (job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, source_identity TEXT NOT NULL, owner_job_id TEXT NOT NULL REFERENCES ik_jobs(id), effects_hash TEXT NOT NULL, PRIMARY KEY(job_id,ordinal));
CREATE TABLE IF NOT EXISTS ik_d1_assertions (ok INTEGER NOT NULL CONSTRAINT IMPORT_ATOMIC_GUARD CHECK(ok=1));

-- Preview plans retain complete consent ledgers and originals without exceeding
-- D1's 2 MB string/row bound. Identity indexes preserve erasure discovery.
CREATE TABLE audience_import_plan_chunks (
 fingerprint TEXT NOT NULL REFERENCES audience_import_plans(fingerprint) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL,
 content TEXT NOT NULL,
 PRIMARY KEY(fingerprint,ordinal)
);
CREATE TABLE audience_import_plan_contacts (
 fingerprint TEXT NOT NULL REFERENCES audience_import_plans(fingerprint) ON DELETE CASCADE,
 contact_id TEXT NOT NULL,
 email TEXT NOT NULL,
 PRIMARY KEY(fingerprint,contact_id,email)
);
CREATE INDEX audience_import_plan_contacts_contact ON audience_import_plan_contacts(contact_id);
CREATE INDEX audience_import_plan_contacts_email ON audience_import_plan_contacts(email);

-- Additive Base import custody. Existing inline plans/originals remain readable;
-- preserve the already-applied 0019 and 0020 migrations and all retained rows.
CREATE TABLE IF NOT EXISTS ik_d1_plan_chunks (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id),
 ordinal INTEGER NOT NULL,
 body TEXT NOT NULL,
 PRIMARY KEY(job_id,ordinal)
);
CREATE TABLE IF NOT EXISTS ik_d1_original_chunks (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id),
 kind TEXT NOT NULL,
 original_key TEXT NOT NULL,
 ordinal INTEGER NOT NULL,
 bytes BLOB NOT NULL,
 PRIMARY KEY(job_id,kind,original_key,ordinal)
);

